for (int i = 1; i <= 10; i++) {
    if (i % 2 == 0) {
        continue;
    }
    System.out.println(i);
}

for (int i = 1, j = 1; i <= 10 && j <= 5; i++, j += 2) {
    System.out.println(i * j);
}

outer: for (int i = 1; i <= 10; i++) {
    inner: for (int j = 1; j <= i; j++) {
        System.out.print("* ");
        if (j >= 5) {
            break outer;
        }
    }
    System.out.println();
}
